// The AI side of the portfolio: career journey, AI experiments, and the math & physics behind modern AI.
const aiJourney=[
{when:'NOV 2025 — NOW',role:'Associate ML Engineer',org:'Rtifact',text:'AI agents, LLM applications, and AIOps for production incidents.',current:true},
{when:'FEB — JUL 2025',role:'AI Intern',org:'DharmikVibes',text:'Generative AI and applied AI.'},
{when:'MAY — JUL 2024',role:'Backend Intern',org:'LivAgain',text:'Backend engineering foundations.'}];

const aiPhysics=[
{id:'softmax',from:'Boltzmann distribution',to:'LLM temperature',title:'Softmax is the Boltzmann distribution.',formula:'p<sub>i</sub> = e<sup>z<sub>i</sub>/T</sup> / Σ<sub>j</sub> e<sup>z<sub>j</sub>/T</sup>',text:'In statistical mechanics, a system occupies a state of energy E with probability proportional to e<sup>−E/kT</sup>. An LLM picks its next token with the same formula: logits play the role of negative energies. The “temperature” setting is literally temperature. Cool it down and the model settles into its most likely answer; heat it up and it explores.'},
{id:'gradient',from:'A ball rolling downhill',to:'Gradient descent',title:'Training is rolling downhill.',formula:'θ ← θ − η ∇L(θ)',text:'A ball in a potential well accelerates along −∇V. Training a network moves its parameters along −∇L, down a loss landscape with millions of dimensions. Momentum optimizers borrow the physics directly: Polyak’s “heavy ball” method lets past velocity carry the parameters through flat regions and small bumps.'},
{id:'entropy',from:'Entropy of a gas',to:'The loss LLMs minimize',title:'Entropy moved from heat to information.',formula:'S = k ln W  →  H = −Σ p log p',text:'Boltzmann counted microscopic arrangements; Shannon measured surprise in a message. Language models train by minimizing cross-entropy, −Σ y log p: how surprised the model is by the real next token. Perplexity, the familiar LLM metric, is just e<sup>H</sup>.'},
{id:'diffusion',from:'Brownian motion',to:'Diffusion models',title:'Diffusion models run Brownian motion backwards.',formula:'x<sub>t</sub> = √ᾱ<sub>t</sub> x<sub>0</sub> + √(1−ᾱ<sub>t</sub>) ε',text:'Einstein explained in 1905 how random molecular kicks make a pollen grain wander. Image diffusion models apply the same idea on purpose: add Gaussian noise step by step until a picture becomes static, then train a network to reverse each step. Generation is noise, slowly un-diffused.'},
{id:'annealing',from:'Cooling metal',to:'Optimization',title:'Slow cooling finds better answers.',formula:'P(accept worse) = e<sup>−ΔE/T</sup>',text:'Metal cooled slowly forms orderly, low-energy crystals; quench it and defects freeze in. In 1983, Kirkpatrick, Gelatt, and Vecchi turned this into simulated annealing: sometimes accept a worse solution, with a probability that shrinks as the “temperature” falls, so the search can escape early traps.'},
{id:'waves',from:'Waves & rotations',to:'Transformer positions',title:'Transformers count positions with waves.',formula:'PE(pos, 2i) = sin(pos / 10000<sup>2i/d</sup>)',text:'A transformer reads every token at once, so it needs another way to know order. The original Transformer stamped each position with sine and cosine waves at geometrically spaced frequencies, like clock hands turning at different speeds. Rotary embeddings (RoPE), used in many modern LLMs, rotate query and key vectors by position, so attention depends on relative distance.'},
{id:'scaling',from:'Power laws',to:'Scaling laws',title:'LLMs follow power laws, like planets.',formula:'L(N) ≈ (N<sub>c</sub> / N)<sup>α</sup>',text:'Physics is full of power laws: Kepler’s T² ∝ a³, Stefan–Boltzmann’s P ∝ T⁴. In 2020, Kaplan and colleagues found that language-model loss falls as a power law in parameters, data, and compute across many orders of magnitude. In 2022, DeepMind’s Chinchilla study used the same approach to show that many large models had been trained on too little data.'},
{id:'free-energy',from:'Free energy',to:'Variational inference',title:'Free energy: fit the data, keep options open.',formula:'F = U − TS  ↔  −ELBO = 𝔼<sub>q</sub>[−log p(x,z)] − H[q]',text:'Helmholtz free energy balances energy against entropy. Variational autoencoders maximize the ELBO, which is a negative variational free energy: explain the data well (low energy) while keeping the approximate posterior spread out (high entropy). Feynman used the same variational principle in statistical mechanics.'},
{id:'hopfield',from:'Spin systems',to:'Neural networks',title:'A Nobel Prize in Physics went to machine learning.',formula:'E = −½ Σ<sub>ij</sub> w<sub>ij</sub> s<sub>i</sub> s<sub>j</sub>',text:'In 2024, John Hopfield and Geoffrey Hinton received the Nobel Prize in Physics for foundational work enabling machine learning with neural networks. Hopfield networks store memories as low-energy states, like spins in a magnet. Hinton’s Boltzmann machine adds temperature, so learning becomes statistical physics.'}];

const aiWork=[
{title:'Is this unusual right now?',formula:'z = (x − μ) / σ',text:'A static threshold asks whether a metric crossed 90%. An anomaly score asks whether a value is unusual for that signal at that time. Comparing a reading against its own recent baseline is how monitoring can flag a rising issue before a fixed threshold pages someone.'},
{title:'Search by meaning, not keywords.',formula:'cos θ = a·b / ‖a‖‖b‖',text:'Retrieval-augmented generation turns runbooks, incidents, and changes into vectors. Two texts about the same failure point in similar directions even when they share no words. The agent retrieves the closest evidence first, so its answer stays grounded.'},
{title:'Attention: Boltzmann again.',formula:'softmax(QKᵀ / √d) V',text:'Inside a transformer, each token scores every other token and turns the scores into weights with a softmax. Dividing by √d keeps the scores from growing with vector size, which would push the softmax toward a near one-hot choice and starve training of useful gradients.'}];

const aiExperiments={
softmax:{label:'LLM temperature',meta:'01 / LLM SAMPLING',tag:'ILLUSTRATIVE LOGITS',title:'“The universe is ___”',formula:'p<sub>i</sub> = e<sup>z<sub>i</sub>/T</sup> / Σ e<sup>z<sub>j</sub>/T</sup>',text:'Five candidate next words with illustrative logits (raw model scores). Lower the temperature and probability piles onto the top word; raise it and unlikely words get a real chance. It is the Boltzmann distribution, with logits as negative energies.'},
gradient:{label:'Gradient descent',meta:'02 / OPTIMIZATION',tag:'CLICK TO DROP THE BALL',title:'Roll down a loss landscape.',formula:'v ← βv − η∇L(θ),  θ ← θ + v',text:'Darker means lower loss. Plain gradient descent from the left edge gets stuck in a shallow valley. Raise momentum to 0.8 and restart: like a heavy ball, it keeps enough velocity to roll over the ridge into the deeper valley. A tiny learning rate crawls; a large one bounces. Click anywhere to start somewhere new. Real networks do this in millions of dimensions.'},
anneal:{label:'Simulated annealing',meta:'03 / SEARCH',tag:'28 CITIES',title:'Cool a route until it settles.',formula:'P(accept worse) = e<sup>−ΔE/T</sup>',text:'Find a short round trip through every city. Each step proposes reversing part of the route. Shorter routes are always accepted; longer ones sometimes, with the Boltzmann probability. Hot, it explores; cooling, it settles. Quench accepts only improvements, so it usually stops on a worse route. Compare them.'},
diffusion:{label:'Diffusion',meta:'04 / GENERATIVE MODELS',tag:'COSINE NOISE SCHEDULE',title:'Dissolve a φ into noise, then bring it back.',formula:'x<sub>t</sub> = √ᾱ<sub>t</sub> x<sub>0</sub> + √(1−ᾱ<sub>t</sub>) ε',text:'Every point is mixed with Gaussian noise until the shape is gone. Thin strokes vanish first, early in the schedule, just as fine texture does in a real image. Denoising walks the same path backwards. Here each reverse step uses the point’s true noise, which is what a perfectly trained model would predict. A real diffusion model learns that prediction from millions of examples.'}};

const softmaxTokens=[['expanding',3.1],['vast',2.6],['beautiful',2.2],['a mystery',1.7],['made of cheese',-.6]];
let aiTab='lab',aiExp='softmax',aiTemp=1;

// Gradient descent on a bumpy two-valley landscape.
const gdBox={x0:-3.2,x1:3.2,y0:-2.2,y1:2.2};
const gdStart=[-3,-.8];
const gd={x:gdStart[0],y:gdStart[1],vx:0,vy:0,lr:.05,mom:0,trail:[],steps:0,acc:0,state:'run',best:null,bg:null};
function gdLoss(x,y){return .07*(x*x+y*y)-1.5*Math.exp(-((x-1.2)**2+(y+.7)**2))-.6*Math.exp(-((x+1.3)**2+(y-.9)**2)/.5)+.12*Math.sin(2.2*x)*Math.cos(1.9*y)}
function gdGrad(x,y){const h=1e-3;return[(gdLoss(x+h,y)-gdLoss(x-h,y))/(2*h),(gdLoss(x,y+h)-gdLoss(x,y-h))/(2*h)]}
function gdSetup(){if(gd.bg)return;const W=200,H=138,off=document.createElement('canvas');off.width=W;off.height=H;const o=off.getContext('2d'),img=o.createImageData(W,H),vals=[];let lo=1e9,hi=-1e9,bx=0,by=0;for(let j=0;j<H;j++)for(let i=0;i<W;i++){const x=gdBox.x0+(i+.5)/W*(gdBox.x1-gdBox.x0),y=gdBox.y1-(j+.5)/H*(gdBox.y1-gdBox.y0),v=gdLoss(x,y);vals.push(v);if(v<lo){lo=v;bx=x;by=y}hi=Math.max(hi,v)}
for(let k=0;k<400;k++){const[gx,gy]=gdGrad(bx,by);bx-=.02*gx;by-=.02*gy}gd.best=gdLoss(bx,by);
const dark=[20,16,34],light=[104,84,138];vals.forEach((v,k)=>{const f=(v-lo)/(hi-lo),band=Math.abs((f*16)%1-.5)<.06?.18:0,m=Math.min(1,Math.pow(f,.8)+band);for(let c=0;c<3;c++)img.data[k*4+c]=dark[c]+(light[c]-dark[c])*m;img.data[k*4+3]=255});o.putImageData(img,0,0);gd.bg=off}
function gdDrop(x,y){Object.assign(gd,{x,y,vx:0,vy:0,trail:[[x,y]],steps:0,acc:0,state:'run'})}
function gdStep(){const[gx,gy]=gdGrad(gd.x,gd.y);gd.vx=gd.mom*gd.vx-gd.lr*gx;gd.vy=gd.mom*gd.vy-gd.lr*gy;gd.x+=gd.vx;gd.y+=gd.vy;gd.steps++;gd.trail.push([gd.x,gd.y]);if(gd.trail.length>400)gd.trail.shift();if(!isFinite(gd.x)||Math.abs(gd.x)>8||Math.abs(gd.y)>8)gd.state='diverged';else if(Math.hypot(gx,gy)<1.5e-3&&Math.hypot(gd.vx,gd.vy)<1e-3)gd.state='settled';else if(gd.steps>=1500)gd.state=Math.hypot(gd.vx,gd.vy)>.01?'bounce':'crawl'}
function gdReadout(){const L=gdLoss(gd.x,gd.y);if(gd.state==='diverged')return`Diverged after ${gd.steps} steps. The learning rate is too large: each step overshoots further than the last.`;if(gd.state==='crawl')return`1,500 steps and still crawling. The learning rate is very small.`;if(gd.state==='bounce')return`Still bouncing after 1,500 steps. The learning rate is too large: every step overshoots the valley floor.`;if(gd.state==='settled')return L-gd.best<.03?`Settled in the deepest valley after ${gd.steps} steps (loss ${L.toFixed(2)}).`:`Stuck in a local minimum after ${gd.steps} steps: loss ${L.toFixed(2)} vs. the best ${gd.best.toFixed(2)}. Try momentum 0.8 or more, or click somewhere else.`;return`Step ${gd.steps} · loss ${L.toFixed(3)}`}
function gdToPx(x,y,w,h){return[(x-gdBox.x0)/(gdBox.x1-gdBox.x0)*w,(gdBox.y1-y)/(gdBox.y1-gdBox.y0)*h]}
function gdDraw(c){gdSetup();const[w,h,x]=fit(c);x.imageSmoothingEnabled=true;x.drawImage(gd.bg,0,0,w,h);x.strokeStyle='#dfd893aa';x.lineWidth=1.5;x.beginPath();gd.trail.forEach(([a,b],i)=>{const[p,q]=gdToPx(a,b,w,h);i?x.lineTo(p,q):x.moveTo(p,q)});x.stroke();if(gd.state!=='diverged'){const[p,q]=gdToPx(gd.x,gd.y,w,h);x.fillStyle='#ffbb89';x.beginPath();x.arc(p,q,6,0,7);x.fill();x.strokeStyle='#141322';x.lineWidth=2;x.stroke()}x.fillStyle='#b0a7c5';x.font='11px monospace';x.fillText('loss landscape · darker = lower',10,h-10)}

// Simulated annealing on a small travelling-salesman tour (2-opt moves).
const sa={cities:[],tour:[],T:0,T0:.25,rate:.0005,len:0,mode:'anneal',state:'idle',tries:0,uphill:0,since:0,results:{}};
function saD(a,b){const p=sa.cities[a],q=sa.cities[b];return Math.hypot(p[0]-q[0],p[1]-q[1])}
function saLen(){let L=0;const t=sa.tour,n=t.length;for(let i=0;i<n;i++)L+=saD(t[i],t[(i+1)%n]);return L}
function saShuffle(){const t=[...sa.cities.keys()];for(let i=t.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[t[i],t[j]]=[t[j],t[i]]}sa.tour=t}
function saCities(){sa.cities=Array.from({length:28},()=>[.05+Math.random()*.9,.08+Math.random()*.84]);sa.results={};saStart('anneal')}
function saStart(mode){saShuffle();Object.assign(sa,{mode,T:mode==='anneal'?sa.T0:0,state:'run',tries:0,uphill:0,since:0,len:saLen()})}
function saStep(){const t=sa.tour,n=t.length,i=1+Math.floor(Math.random()*(n-2)),j=i+1+Math.floor(Math.random()*(n-1-i)),a=t[i-1],b=t[i],c=t[j],d=t[(j+1)%n],delta=saD(a,c)+saD(b,d)-saD(a,b)-saD(c,d);sa.tries++;sa.since++;if(delta<-1e-12||(sa.T>0&&Math.random()<Math.exp(-delta/sa.T))){if(delta>0)sa.uphill++;if(delta<-1e-12)sa.since=0;for(let l=i,r=j;l<r;l++,r--)[t[l],t[r]]=[t[r],t[l]];sa.len+=delta}if(sa.mode==='anneal'){sa.T*=1-sa.rate;if(sa.T<4e-4)sa.T=0}if(sa.T===0&&sa.since>4000){sa.state='done';sa.len=saLen();sa.results[sa.mode]=sa.len}}
function saReadout(){const r=sa.results,cmp=[r.anneal&&`anneal ${r.anneal.toFixed(2)}`,r.quench&&`quench ${r.quench.toFixed(2)}`].filter(Boolean).join(' · ');if(sa.state==='done')return`${sa.mode==='anneal'?'Annealed':'Quenched'}: route length ${sa.len.toFixed(2)}. ${cmp?'Results on these cities: '+cmp+'.':''}`;return`${sa.mode==='anneal'?`T = ${sa.T.toFixed(4)}`:'T = 0 (quench)'} · route length ${sa.len.toFixed(2)} · worse moves accepted: ${sa.uphill}`}
function saDraw(c){const[w,h,x]=fit(c);x.fillStyle='#141120';x.fillRect(0,0,w,h);const heat=sa.mode==='anneal'?Math.min(1,sa.T/sa.T0):0,mix=(a,b)=>Math.round(a+(b-a)*heat);x.strokeStyle=`rgb(${mix(223,255)},${mix(216,187)},${mix(147,137)})`;x.lineWidth=1.6;x.beginPath();sa.tour.forEach((k,i)=>{const[p,q]=sa.cities[k];i?x.lineTo(p*w,q*h):x.moveTo(p*w,q*h)});x.closePath();x.stroke();x.fillStyle='#f3e7d4';sa.cities.forEach(([p,q])=>x.fillRect(p*w-3,q*h-3,6,6));x.fillStyle='#b0a7c5';x.font='11px monospace';x.fillText(sa.state==='done'?'settled':heat>.5?'hot: exploring':heat>.05?'cooling':'cold: settling',10,h-10)}

// Forward and reverse diffusion on a point cloud shaped like φ.
const df={pts:[],t:0,target:0};
function dfGauss(){let u=0,v=0;while(!u)u=Math.random();while(!v)v=Math.random();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)}
function dfSetup(){if(df.pts.length)return;for(let k=0;k<520;k++){let x,y;if(k<320){const a=Math.random()*Math.PI*2;x=.55*Math.cos(a)+dfGauss()*.018;y=.42*Math.sin(a)+dfGauss()*.018}else{x=dfGauss()*.018;y=-1+Math.random()*2}df.pts.push({x,y,ex:dfGauss(),ey:dfGauss()})}}
function dfAlpha(t){return Math.cos((t+.008)/1.008*Math.PI/2)**2}
function dfReadout(){const a=dfAlpha(df.t);return`t = ${df.t.toFixed(2)} · signal √ᾱ = ${Math.sqrt(a).toFixed(2)} · noise √(1−ᾱ) = ${Math.sqrt(1-a).toFixed(2)}`}
function dfDraw(c){const[w,h,x]=fit(c);x.fillStyle='#141120';x.fillRect(0,0,w,h);const a=dfAlpha(df.t),s=Math.sqrt(a),n=Math.sqrt(1-a),sc=Math.min(w,h)*.21,cx=w/2,cy=h/2,mix=(p,q)=>Math.round(p+(q-p)*df.t);x.fillStyle=`rgb(${mix(223,207)},${mix(216,179)},${mix(147,236)})`;df.pts.forEach(p=>x.fillRect(cx+(s*1.7*p.x+n*p.ex)*sc-1.2,cy-(s*1.7*p.y+n*p.ey)*sc-1.2,2.4,2.4));x.fillStyle='#b0a7c5';x.font='11px monospace';x.fillText(df.t<.02?'data: x₀':df.t>.98?'pure noise: x₁':'mixing signal and noise',10,h-10)}

function aiStep(dt,instant){if(aiExp==='gradient'&&gd.state==='run'){if(instant){while(gd.state==='run')gdStep()}else{gd.acc+=dt;while(gd.acc>.025&&gd.state==='run'){gd.acc-=.025;gdStep()}}}
if(aiExp==='anneal'&&sa.state==='run'){let k=instant?1e6:30;while(k-->0&&sa.state==='run')saStep()}
if(aiExp==='diffusion'&&df.t!==df.target){const d=instant?1:dt*.4;df.t=df.t<df.target?Math.min(df.target,df.t+d):Math.max(df.target,df.t-d);const r=document.querySelector('#ai-t');if(r)r.value=df.t}}
function aiTick(){const el=document.querySelector('#ai-readout');if(!el)return;el.textContent=aiExp==='gradient'?gdReadout():aiExp==='anneal'?saReadout():aiExp==='diffusion'?dfReadout():el.textContent}
let aiLast=0;function aiFrame(now){requestAnimationFrame(aiFrame);const dt=Math.min((now-aiLast)/1000,.05);aiLast=now;const w=wins.get('ai'),c=document.querySelector('#ai-canvas');if(w&&!w.hidden&&c){aiStep(dt,paused);if(aiExp==='gradient')gdDraw(c);if(aiExp==='anneal')saDraw(c);if(aiExp==='diffusion')dfDraw(c);aiTick()}}requestAnimationFrame(aiFrame);

function renderExperiment(box){const e=aiExperiments[aiExp];const controls={softmax:`<label>Temperature <input id="ai-temp" type="range" min="0.1" max="3" step="0.05" value="${aiTemp}"><output id="ai-temp-out"></output></label>`,gradient:`<label>Learning rate <input id="ai-lr" type="range" min="0.005" max="0.6" step="0.005" value="${gd.lr}"><output id="ai-lr-out">${gd.lr}</output></label><label>Momentum <input id="ai-mom" type="range" min="0" max="0.95" step="0.05" value="${gd.mom}"><output id="ai-mom-out">${gd.mom}</output></label><button class="filter" id="ai-drop">Restart</button>`,anneal:`<label>Cooling <input id="ai-cool" type="range" min="0.0002" max="0.003" step="0.0001" value="${sa.rate}"><output id="ai-cool-out"></output></label><button class="filter" id="ai-anneal">Anneal</button><button class="filter" id="ai-quench">Quench</button><button class="filter" id="ai-cities">New cities</button>`,diffusion:`<label>Time t <input id="ai-t" type="range" min="0" max="1" step="0.01" value="${df.t}"></label><button class="filter" id="ai-noise">Add noise</button><button class="filter" id="ai-denoise">Denoise</button>`}[aiExp];
box.innerHTML=`<div class="card-meta"><span>${e.meta}</span><span>${e.tag}</span></div><h3>${e.title}</h3>${aiExp==='softmax'?'<div class="softmax-bars" aria-live="polite"></div>':`<canvas id="ai-canvas" class="lab-view ai-canvas${aiExp==='gradient'?' clickable':''}" aria-label="${e.label} interactive experiment"></canvas>`}<div class="lab-controls">${controls}</div><p class="demo-note" id="ai-readout"${aiExp==='softmax'?' aria-live="polite"':''}></p><div class="lab-equation">${e.formula}</div><p class="ai-exp-text">${e.text}</p>`;
const $=s=>box.querySelector(s);
if(aiExp==='softmax'){const range=$('#ai-temp'),update=()=>{aiTemp=+range.value;const w=softmaxTokens.map(([,z])=>Math.exp(z/aiTemp)),s=w.reduce((a,b)=>a+b,0),p=w.map(v=>v/s),H=-p.reduce((a,v)=>a+(v>0?v*Math.log2(v):0),0);$('#ai-temp-out').value='T = '+aiTemp.toFixed(2);$('.softmax-bars').innerHTML=softmaxTokens.map(([t],i)=>`<div class="softmax-row"><span>${t}</span><i style="--p:${(p[i]*100).toFixed(1)}%"></i><b>${(p[i]*100).toFixed(1)}%</b></div>`).join('');$('#ai-readout').textContent=`Entropy: ${H.toFixed(2)} bits of uncertainty. ${aiTemp<.5?'Cold: the model almost always picks the top word.':aiTemp>1.6?'Hot: unlikely words get real chances.':'Near T = 1: the model’s own probabilities.'}`};range.oninput=update;update()}
if(aiExp==='gradient'){gdSetup();$('#ai-lr').oninput=e=>{gd.lr=+e.target.value;$('#ai-lr-out').value=gd.lr};$('#ai-mom').oninput=e=>{gd.mom=+e.target.value;$('#ai-mom-out').value=gd.mom};$('#ai-drop').onclick=()=>gdDrop(...gdStart);$('#ai-canvas').onclick=ev=>{const r=ev.currentTarget.getBoundingClientRect();gdDrop(gdBox.x0+(ev.clientX-r.left)/r.width*(gdBox.x1-gdBox.x0),gdBox.y1-(ev.clientY-r.top)/r.height*(gdBox.y1-gdBox.y0))};if(!gd.trail.length)gdDrop(gd.x,gd.y)}
if(aiExp==='anneal'){if(!sa.cities.length)saCities();const cool=$('#ai-cool'),label=()=>{$('#ai-cool-out').value=sa.rate<.0004?'slow':sa.rate>.0015?'fast':'medium'};cool.oninput=()=>{sa.rate=+cool.value;label()};label();$('#ai-anneal').onclick=()=>saStart('anneal');$('#ai-quench').onclick=()=>saStart('quench');$('#ai-cities').onclick=saCities}
if(aiExp==='diffusion'){dfSetup();$('#ai-t').oninput=e=>{df.t=df.target=+e.target.value};$('#ai-noise').onclick=()=>df.target=1;$('#ai-denoise').onclick=()=>df.target=0}}

function renderAI(el,focus){el.innerHTML=`<span class="eyebrow">THE AI LAB / WHERE AI MEETS PHYSICS</span><h2>The math behind<br>the machines.</h2><p class="lede">Four small experiments and the ideas behind them. The math is real; the scale is tiny.</p><div class="filters" role="group" aria-label="Notebook section">${[['lab','Experiments'],['physics','Physics inside AI'],['work','Math in my work']].map(([k,l])=>`<button class="filter ${aiTab===k?'active':''}" aria-pressed="${aiTab===k}" data-ai-tab="${k}">${l}</button>`).join('')}</div>${aiTab==='lab'?`<div class="ai-exp-picker" role="group" aria-label="Experiment">${Object.entries(aiExperiments).map(([k,e])=>`<button class="${aiExp===k?'active':''}" aria-pressed="${aiExp===k}" data-ai-pick="${k}">${e.label}</button>`).join('')}</div><div class="ai-exp" id="ai-exp"></div>`:`<div class="ai-concepts">${(aiTab==='physics'?aiPhysics:aiWork).map((c,i)=>`<article class="note ai-concept"${c.id?` id="ai-topic-${c.id}"`:''}><span class="meta">${String(i+1).padStart(2,'0')} / ${c.from?`${c.from} → ${c.to}`.toUpperCase():'FROM THE WORKBENCH'}</span><h3>${c.title}</h3><div class="formula">${c.formula}</div><p>${c.text}</p></article>`).join('')}</div>`}<div class="detail-actions"><button class="primary" data-open="experience">See where I use this</button><button class="text-button" data-open="atlas">Visit the physics atlas</button></div>`;
el.querySelectorAll('[data-ai-tab]').forEach(b=>b.onclick=()=>{aiTab=b.dataset.aiTab;renderAI(el);el.scrollTop=0});
el.querySelectorAll('[data-ai-pick]').forEach(b=>b.onclick=()=>{aiExp=b.dataset.aiPick;el.querySelectorAll('[data-ai-pick]').forEach(o=>{o.classList.toggle('active',o===b);o.setAttribute('aria-pressed',o===b)});renderExperiment(el.querySelector('#ai-exp'))});
if(aiTab==='lab')renderExperiment(el.querySelector('#ai-exp'));
if(focus){const t=el.querySelector('#ai-topic-'+focus);if(t){t.classList.add('focused');requestAnimationFrame(()=>t.scrollIntoView({block:'start',behavior:paused?'instant':'smooth'}))}}}

function renderJourney(el){const actions=el.querySelector('.detail-actions');if(!actions)return;const block=document.createElement('div');block.className='ai-journey-window';block.innerHTML=`<h3>The journey so far</h3><ol class="ai-timeline">${aiJourney.map(j=>`<li class="${j.current?'current':''}"><span class="meta">${j.when}</span><strong>${j.role} <span>· ${j.org}</span></strong><p>${j.text}</p></li>`).join('')}</ol><p class="experience-education"><span class="meta">EDUCATION</span> Indian Institute of Information Technology Vadodara</p>`;actions.before(block)}

Object.assign(titles,{ai:'The AI lab'});
const renderBeforeAI=renderApp;renderApp=function(id,el){if(id==='ai')renderAI(el);else{renderBeforeAI(id,el);if(id==='experience')renderJourney(el)}};
document.addEventListener('click',e=>{const exp=e.target.closest('[data-ai-exp]'),topic=e.target.closest('[data-ai-topic]');if(!exp&&!topic)return;const w=openApp('ai'),el=w.querySelector('.window-content');if(exp){aiTab='lab';aiExp=exp.dataset.aiExp;renderAI(el);el.scrollTop=0}else{aiTab='physics';renderAI(el,topic.dataset.aiTopic)}});
